def retry(func):
    def wrapper(*args, **kwargs):
        attempts = 0
        while True:
            try:
                return func(*args, **kwargs)
            except Exception:
                attempts += 1
                if attempts >= 3:
                    raise
    return wrapper

@retry
def unstable():
    import random
    if random.random() < 0.5:
        raise ValueError('fail')
    return 42

print(unstable())

