import inspect
import functools

def authorize(roles):
    def decorator(func):
        sig = inspect.signature(func)
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if not args:
                raise TypeError('First argument must be a user dict')
            user = args[0]
            if not isinstance(user, dict) or 'role' not in user:
                raise PermissionError('User missing role')
            if user['role'] not in roles:
                raise PermissionError('Access denied')
            return func(*args, **kwargs)
        return wrapper
    return decorator

